import bisect

def solve(nums1, nums2):
    h1 = sorted(nums2)
    freq_nums2 = {}
    for num in nums2:
        freq_nums2[num] = freq_nums2.get(num, 0) + 1
    result = []
    for num in nums1:
        left = bisect.bisect_left(h1, num)
        right = bisect.bisect_right(h1, num)
        count_in_nums2 = right - left
        if count_in_nums2 > 0 and freq_nums2.get(num, 0) > 0:
            result.append(num)
            freq_nums2[num] -= 1
    return result

